mapper.select:
select id, owner_user_id, content_fingerprint, prompt_fingerprint, prompt, content, think_used, last_accessed_at, last_generated_at, created_at, updated_at
from pw_card_ai_cache
where owner_user_id = #{ownerUserId}
  and content_fingerprint = #{fingerprint}
limit 1

mapper.update:
update pw_card_ai_cache
set last_accessed_at = #{accessedAt}
where owner_user_id = #{ownerUserId}
  and content_fingerprint = #{fingerprint}
  and (last_accessed_at is null or last_accessed_at < #{minEligibleBefore})
